DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PAM 008", "old_status": "worked_shared_stimulus", "status": "ready", "question_id": "2e905225-ae8b-63b0-1de2-dbd31cbbca60", "stem": "Which function is represented by the graph?", "choices": [{"key": "A", "text": "\\(f(x)=(x+1)(x-2)^2\\)"}, {"key": "B", "text": "\\(f(x)=(x-1)(x+2)^2\\)"}, {"key": "C", "text": "\\(f(x)=(x+1)(x-2)\\)"}, {"key": "D", "text": "\\(f(x)=(x-2)(x+1)^2\\)"}], "type": "mcq", "correct": "A", "explanation": "The graph crosses the x-axis at −1, so (x + 1) is a factor of odd multiplicity. It touches and turns at x = 2, so (x − 2) is squared. It rises to the right and passes through (0, 4), all consistent with (x + 1)(x − 2)².", "topic": "Polynomials & Quadratic Functions", "note": "Recovered original shared graph from HOA 008 page 7; matched against all four choices on page 312.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 312, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}, "crop": {"page": 7, "rect": [145, 337, 487, 619]}, "before": {"stem": "The graph plotted below represents which of the following functions?", "choices": [{"key": "A", "text": "f(x) = (x + 1)(x − 2)²"}, {"key": "B", "text": "f(x) = (x − 1)(x + 2)²"}, {"key": "C", "text": "f(x) = (x + 1)(x − 2)"}, {"key": "D", "text": "f(x) = (x − 2)(x + 1)²"}], "correct": "A", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}}, {"id": "clean:PAM 022", "old_status": "worked_shared_stimulus", "status": "ready", "question_id": "1aa73a52-a5fb-57b2-8dbc-acb8c5312605", "stem": "The plotted curve P represents \\(f(x)=-x^2+ax+b\\). What are a and b?", "choices": [{"key": "A", "text": "a = −1; b = −3"}, {"key": "B", "text": "a = −3; b = −1"}, {"key": "C", "text": "a = −1.5; b = −1"}, {"key": "D", "text": "a = −2.5; b = −0.5"}], "type": "mcq", "correct": "B", "explanation": "The y-intercept is −1, so b = −1. The axis of symmetry is x = −1.5. For −x² + ax + b, the vertex x-coordinate is a/2, so a = −3. The resulting vertex is (−1.5, 1.25), matching the graph.", "topic": "Polynomials & Quadratic Functions", "note": "Recovered shared parabola from HOA 047 page 34 and checked the options on page 320.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 320, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}, "crop": {"page": 34, "rect": [72, 391, 408, 760]}}, {"id": "clean:PAM 028", "old_status": "worked_shared_stimulus", "status": "ready", "question_id": "cfbb15c4-3b8c-56e2-be53-2297d361d2af", "stem": "The graph represents \\(g(x)=ax^2+bx+c\\). Which statement is NOT true?", "choices": [{"key": "A", "text": "a > 0"}, {"key": "B", "text": "b > 0"}, {"key": "C", "text": "c > 0"}, {"key": "D", "text": "3a + b = 0"}], "type": "mcq", "correct": "B", "explanation": "The parabola opens upward, so a > 0. Its y-intercept is positive, so c > 0. Its axis is x = 1.5 = −b/(2a), giving b = −3a < 0 and 3a + b = 0. Therefore b > 0 is the false statement.", "topic": "Polynomials & Quadratic Functions", "note": "Recovered the shared graph from HOA 054 page 38; options checked on page 323.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 323, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}, "crop": {"page": 38, "rect": [145, 335, 502, 655]}}, {"id": "clean:PAM 020", "old_status": "worked_shared_stimulus", "status": "ready", "question_id": "27eccf7a-7f35-582d-a2ad-247886d20c10", "stem": "For the function f shown in the graph, what does f(x) approach as x approaches positive infinity?", "choices": [{"key": "A", "text": "0"}, {"key": "B", "text": "1"}, {"key": "C", "text": "5.5"}, {"key": "D", "text": "Positive infinity"}], "type": "mcq", "correct": "D", "explanation": "The right-hand branch rises without bound. Thus as x grows without bound, f(x) also grows without bound, so the limit is positive infinity. The left-hand horizontal behavior does not describe this limit.", "topic": "Functions, Transformations & Graphs", "note": "Reunited options on page 319 with the original shared graph in PAM 019 page 318.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 319, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}, "crop": {"page": 318, "rect": [149, 142, 493, 522]}}, {"id": "clean:PSD 050", "old_status": "worked_shared_stimulus", "status": "ready", "question_id": "2263b7e6-d79c-5caa-82d4-54c4be96e9ef", "stem": "The table gives the scores of all students on a test. What is the median score?", "choices": [{"key": "A", "text": "8"}, {"key": "B", "text": "60"}, {"key": "C", "text": "70"}, {"key": "D", "text": "80"}], "type": "mcq", "correct": "C", "explanation": "There are 26 scores, so the median is the average of the 13th and 14th sorted scores. Scores of 70 occupy positions 9 through 16. Thus both middle scores are 70 and the median is 70.", "topic": "Statistics, Probability & Data Analysis", "note": "Restored the shared data from the chart under PSD 049 page 185; choices checked on page 186.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 186, "extra_sources": [], "assets": {"html": "<table><thead><tr><th>Score</th><th>50</th><th>60</th><th>70</th><th>80</th><th>90</th></tr></thead><tbody><tr><th>Number of students</th><td>4</td><td>4</td><td>8</td><td>5</td><td>5</td></tr></tbody></table>"}}, {"id": "clean:PSD 051", "old_status": "worked_shared_stimulus", "status": "ready", "question_id": "aa22ba4d-2669-5fba-8dee-bf7b2a052d54", "stem": "The table gives the scores of all students on a test. What is the range of the scores?", "choices": [{"key": "A", "text": "40"}, {"key": "B", "text": "3"}, {"key": "C", "text": "10"}, {"key": "D", "text": "20"}], "type": "mcq", "correct": "A", "explanation": "The smallest score is 50 and the largest is 90. The range is 90 − 50 = 40.", "topic": "Statistics, Probability & Data Analysis", "note": "Restored shared data from PSD 049 page 185; options checked on page 186.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 186, "extra_sources": [], "assets": {"html": "<table><thead><tr><th>Score</th><th>50</th><th>60</th><th>70</th><th>80</th><th>90</th></tr></thead><tbody><tr><th>Number of students</th><td>4</td><td>4</td><td>8</td><td>5</td><td>5</td></tr></tbody></table>"}}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='source_review_20260928' AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_20260928','source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
